fn hook(id:&str,item:&str)->core::ops::ControlFlow<bool>{if (item.starts_with("arcadiandream:")&&item.ends_with("_shot"))||item=="arcadiandream:hourai_elixir"{return core::ops::ControlFlow::Break(false)} if id=="minecraft:impaling"&&item=="arcadiandream:nue_trident"{core::ops::ControlFlow::Break(horizon_world::loot::arcadian_settings::config()["nueTridentOptions"]["canHaveImpaling"].as_bool().unwrap_or(true))}else{core::ops::ControlFlow::Continue(())}}
